@Entity
public class Token {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false)
    private String tokenValue;

    @Column(name = "user_id", nullable = false)
    private Long userId;

    @Column(name = "token_type", nullable = false)
    private String tokenType;

    @Column(name = "issued_at", nullable = false)
    private LocalDateTime issuedAt;

    @Column(name = "expires_at", nullable = false)
    private LocalDateTime expiresAt;

    @Column(name = "is_revoked", nullable = false)
    private Boolean isRevoked = false;

    @Column(name = "is_consumed", nullable = false)
    private Boolean isConsumed = false;

    @Column(name = "refresh_token", columnDefinition = "TEXT")
    private String refreshToken; // For refresh token storage

    // Constructors
    public Token() {}

    public Token(String tokenValue, Long userId, String tokenType) {
        this.tokenValue = tokenValue;
        this.userId = userId;
        this.tokenType = tokenType;
        this.issuedAt = LocalDateTime.now();
        this.expiresAt = calculateExpiration();
        this.isRevoked = false;
        this.isConsumed = false;
    }

    // Getters and Setters
    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }

    public String getTokenValue() { return tokenValue; }
    public void setTokenValue(String tokenValue) { this.tokenValue = tokenValue; }

    public Long getUserId() { return userId; }
    public void setUserId(Long userId) { this.userId = userId; }

    public String getTokenType() { return tokenType; }
    public void setTokenType(String tokenType) { this.tokenType = tokenType; }

    public LocalDateTime getIssuedAt() { return issuedAt; }
    public void setIssuedAt(LocalDateTime issuedAt) { this.issuedAt = issuedAt; }

    public LocalDateTime getExpiresAt() { return expiresAt; }
    public void setExpiresAt(LocalDateTime expiresAt) { this.expiresAt = expiresAt; }

    public Boolean getIsRevoked() { return isRevoked; }
    public void setIsRevoked(Boolean isRevoked) { this.isRevoked = isRevoked; }

    public Boolean getIsConsumed() { return isConsumed; }
    public void setIsConsumed(Boolean isConsumed) { this.isConsumed = isConsumed; }

    public String getRefreshToken() { return refreshToken; }
    public void setRefreshToken(String refreshToken) { this.refreshToken = refreshToken; }

    // Private method to calculate expiration based on token type
    private LocalDateTime calculateExpiration() {
        if ("access_token".equals(tokenType)) {
            return LocalDateTime.now().plusSeconds(10 * 60); // 10 minutes
        } else if ("refresh_token".equals(tokenType)) {
            return LocalDateTime.now().plusDays(24); // 24 hours
        } else if ("one_time_token".equals(tokenType)) {
            return LocalDateTime.now().plusMinutes(5); // 5 minutes
        }
        return LocalDateTime.now().plusSeconds(10 * 60);
    }

