    public String toString() {
        return "Token{" +
                "id=" + id +
                ", tokenValue='" + tokenValue + '\'' +
                ", userId=" + userId +
                ", tokenType='" + tokenType + '\'' +
                ", issuedAt=" + issuedAt +
                ", expiresAt=" + expiresAt +
                ", isRevoked=" + isRevoked +
                ", isConsumed=" + isConsumed +
                '}';
    }
}
