package com.example.auth.background;

import com.example.auth.token.Token;
import com.example.auth.token.TokenRepository;
import org.springframework.scheduled.annotation.task.TaskScheduler;
import org.springframework.stereotype.Component;
import org.springframework.util.StringUtils;

import java.time.LocalDateTime;
import java.util.List;
import java.util.stream.Collectors;

@Component
public class CleanupTask {

    private final TokenRepository tokenRepository;

    public CleanupTask(TokenRepository tokenRepository) {
        this.tokenRepository = tokenRepository;
    }

    @Scheduled(fixedRateValue = 10000) // Every 10 seconds
    public void performCleanup() {
        try {
            // Get all tokens from database
            List<Token> allTokens = tokenRepository.findAll();

            int deletedCount = 0;

            // Filter and delete tokens that are:
            // 1. Expired (expires_at is in the past)
            // 2. Revoked (is_revoked is true)
            // 3. Consumed (is_consumed is true)

            Token[] tokensToDelete = allTokens.stream()
                    .filter(token -> {
                        boolean shouldDelete = false;

                        // Check if expired
                        if (token.getExpiresAt() != null && 
                            token.getExpiresAt().isBefore(LocalDateTime.now())) {
                            shouldDelete = true;
                        }

                        // Check if revoked
                        if (token.getIsRevoked() && !token.getIsRevoked().equals(false)) {
                            shouldDelete = true;
                        }

                        // Check if consumed
                        if (token.getIsConsumed() && !token.getIsConsumed().equals(false)) {
                            shouldDelete = true;
                        }

                        return shouldDelete;
                    })
                    .collect(Collectors.toList());

            // Delete tokens that need to be removed
            for (Token token : tokensToDelete) {
                // Remove from database
                tokenRepository.delete(token);
                deletedCount++;
            }

            // Log the cleanup action
            System.out.println("[CLEANUP] Deleted " + deletedCount + " tokens");

        } catch (Exception e) {
            System.err.println("Error during cleanup: " + e.getMessage());
        }
    }
}
